fn fibonacci(n: usize) -> Vec<i32> {
    if n == 0 {
        return vec![];
    } else if n == 1 {
        return vec![0];
    }

    let mut fib = vec![0; n];
    fib[0] = 0;
    fib[1] = 1;

    for i in 2..n {
        fib[i] = fib[i - 1] + fib[i - 2];
    }

    fib
}